seo.schema:
{
    "@context": "https://schema.org",
    "@graph": [
        {
            "@type": "LocalBusiness",
            "@id": "{website}/#localbusiness",
            "name": "{business}",
            "url": "{website}",
            "telephone": "{tel}",
            "image": "{lb_logo}",
            "description": "{business} connects {state} property owners with local mold inspection and remediation specialists, providing mold testing, black mold removal, safe containment, and moisture control for homes and businesses.",
            "areaServed": {
                "@type": "City",
                "name": "{city}"
            },
            "priceRange": "$$",
            "openingHours": "Mo-Su 00:00-23:59",
            "address": {
                "@type": "PostalAddress",
                "addressLocality": "{city}",
                "addressRegion": "{SS}",
                "addressCountry": "US"
            }
        },
        {
            "@type": "WebSite",
            "@id": "{website}/#website",
            "url": "{website}",
            "name": "{business}",
            "publisher": {
                "@id": "{website}/#localbusiness"
            }
        }
    ]
}

{
    "@context": "https://schema.org",
    "@graph": [
        {
            "@type": "ContactPage",
            "@id": "{website}/contact-us/#contactpage",
            "url": "{website}/contact-us/",
            "name": "Contact {business}",
            "description": "Call or email {business} to be connected with a local mold remediation provider in {city_state}.",
            "isPartOf": {
                "@id": "{website}/#website"
            },
            "about": {
                "@id": "{website}/#localbusiness"
            }
        },
        {
            "@type": "LocalBusiness",
            "@id": "{website}/#localbusiness",
            "name": "{business}",
            "url": "{website}",
            "telephone": "{tel}",
            "areaServed": {
                "@type": "City",
                "name": "{city}"
            },
            "email": "{email}",
            "contactPoint": {
                "@type": "ContactPoint",
                "telephone": "{tel}",
                "email": "{email}",
                "contactType": "customer service",
                "areaServed": "US",
                "availableLanguage": "English"
            }
        }
    ]
}

{
    "@context": "https://schema.org",
    "@graph": [
        {
            "@type": "AboutPage",
            "@id": "{website}/about-us/#aboutpage",
            "url": "{website}/about-us/",
            "name": "About {business}",
            "description": "How {business} connects {city_state} property owners with independent local mold remediation providers.",
            "isPartOf": {
                "@id": "{website}/#website"
            },
            "about": {
                "@id": "{website}/#localbusiness"
            }
        },
        {
            "@type": "LocalBusiness",
            "@id": "{website}/#localbusiness",
            "name": "{business}",
            "url": "{website}",
            "telephone": "{tel}",
            "areaServed": {
                "@type": "City",
                "name": "{city}"
            }
        }
    ]
}
